<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$events=$pdo->query("SELECT e.id,e.name,e.event_date,COUNT(r.id) round_count FROM bdc_test_events e JOIN bdc_test_scoring_rounds r ON r.event_id=e.id AND r.status<>'archived' GROUP BY e.id,e.name,e.event_date ORDER BY e.event_date DESC,e.name")->fetchAll();$eventId=(int)($_GET['event_id']??0);$rounds=[];if($eventId>0){$s=$pdo->prepare("SELECT id,round_type,division,status FROM bdc_test_scoring_rounds WHERE event_id=:e AND status<>'archived' ORDER BY division,FIELD(round_type,'heats','semifinal','final'),id");$s->execute(['e'=>$eventId]);$rounds=$s->fetchAll();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Live Screen Projector</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.card{border-radius:16px}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../scoring-tests/select-mode.php">Scoring Tests</a><a class="btn btn-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4"><div class="alert alert-warning fw-bold">TEST MODE · Projection data comes only from Scoring Tests.</div><h1 class="h2">Test Live Screen Projector</h1><p class="text-muted mb-4">Select the Test event first, then category and competition round.</p><?php if($eventId<1):?><div class="row g-3"><?php foreach($events as $e):?><div class="col-lg-6"><div class="card shadow-sm"><div class="card-body"><h2 class="h5"><?=e($e['name'])?></h2><div class="text-muted"><?=e((string)$e['event_date'])?> · <?=(int)$e['round_count']?> round(s)</div><a class="btn btn-warning w-100 mt-3" href="?event_id=<?=(int)$e['id']?>">Select Test Event</a></div></div></div><?php endforeach;?></div><?php else:$selected=array_values(array_filter($events,fn($e)=>(int)$e['id']===$eventId));?><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h4 mb-0"><?=e($selected[0]['name']??'Test Event')?></h2><a class="btn btn-outline-secondary" href="./test-index.php">Change Event</a></div><div class="row g-3"><?php foreach($rounds as $r):?><div class="col-lg-6"><div class="card shadow-sm"><div class="card-body"><h3 class="h5"><?=e(ucwords(str_replace('_',' ',$r['division'])))?></h3><div class="text-muted"><?=e(ucfirst($r['round_type']))?></div><a class="btn btn-danger w-100 mt-3" href="test-control.php?round_id=<?=(int)$r['id']?>">Projection Control</a></div></div></div><?php endforeach;?></div><?php endif;?></main></body></html>